```cpp
#include <iostream>
#include <fstream>
#include <string>

int main() {
    std::string palabra_a_contar;
    int apariciones = 0;

    // Pide al usuario una palabra para contar
    std::cout << "Introduce una palabra para contar: ";
    std::getline(std::cin, palabra_a_contar);

    std::ifstream archivo("archivo_de_texto.txt"); // Reemplaza con el nombre de tu archivo de texto real

    if (!archivo.is_open()) { // Comprueba si se abrió correctamente
        std::cerr << "No se pudo abrir el archivo de texto.\n";
        return 1;
    }

    std::string linea;
    while (std::getline(archivo, linea)) { // Lee línea por línea hasta el final del archivo
        size_t pos = 0;
        while ((pos = linea.find(palabra_a_contar, pos)) != std::string::npos) { // Busca la palabra dentro de cada línea
            apariciones++; // Incrementa el conteo de apariciones cada vez que se encuentra la palabra
            pos += palabra_a_contar.length(); // Salta al siguiente caracter después de la última aparición
        }
    }

    archivo.close();

    std::cout << "La palabra '" << palabra_a_contar << "' aparece " << apariciones << " veces en el archivo de texto." << std::endl;

    return 0;
}
```

